-- =============================================================================
-- MIGRATION: f2_lugares
-- F2 T2: tabelas de lugar (`lugares`, `lugar_aliases`), `video_lugares` e a semente v1.
-- Aditivo; rollback: drop table video_lugares, lugar_aliases, lugares;
-- O bloco entre os marcadores SEMENTE-LUGARES é gerado por apps/web/scripts/gerar-semente-lugares.ts
-- a partir de apps/web/data/lugares/semente-v1.json; NÃO edite à mão (o teste semente.test.ts compara).
-- =============================================================================
set lock_timeout = '5s';

create table if not exists public.lugares (
  slug text primary key,
  pais_iso2 char(2) not null,
  nivel text not null check (nivel in ('pais', 'local'))
);

create table if not exists public.lugar_aliases (
  alias_norm text primary key,
  slug text not null references public.lugares (slug) on delete cascade,
  ambiguo boolean not null default false,
  semente_versao smallint not null
);
create index if not exists lugar_aliases_slug_idx on public.lugar_aliases (slug);

-- video_id sem FK: serve aos dois donos (competidor e próprio); órfãos podados pela T6.
create table if not exists public.video_lugares (
  video_id uuid primary key,
  site_id uuid not null references public.sites (id) on delete cascade,
  origem text not null check (origem in ('competidor', 'proprio')),
  chaves text[] not null,
  fonte text not null check (fonte in ('texto', 'texto+coordenada')),
  entrada_hash text not null,
  semente_versao smallint not null,
  computado_em timestamptz not null
);
create index if not exists video_lugares_site_origem_idx on public.video_lugares (site_id, origem);
create index if not exists video_lugares_chaves_gin on public.video_lugares using gin (chaves);

alter table public.lugares enable row level security;
alter table public.lugar_aliases enable row level security;
alter table public.video_lugares enable row level security;

-- lugares/lugar_aliases: sem site_id, RLS ligada e nenhuma policy (só o serviço lê e grava).
revoke all on public.lugares, public.lugar_aliases from public, anon, authenticated;
grant select, insert, update, delete on public.lugares, public.lugar_aliases to service_role;

-- video_lugares: leitura sensível por can_edit_site (nunca site_visible); escrita só service_role.
revoke all on public.video_lugares from public, anon, authenticated;
grant select on public.video_lugares to authenticated;
grant select, insert, update, delete on public.video_lugares to service_role;

drop policy if exists video_lugares_select on public.video_lugares;
create policy video_lugares_select on public.video_lugares
  for select to authenticated using (public.can_edit_site(site_id));

